
const KEY='azhi6-story-v1';const chapters=[{name:'第一章・重新出發',title:'從海線出發',desc:'阿志決定離開舊日陰影，用自己的方式在城市重新站穩腳步。',need:0},{name:'第二章・夜市新星',title:'逢甲的第一筆生意',desc:'夜市的燈火不會替任何人停留。你需要找到夥伴，完成第一份正式委託。',need:30},{name:'第三章・極速之夜',title:'海線公路挑戰',desc:'改車師阿凱提出挑戰：真正的名聲，必須在賽道上靠技術贏得。',need:70},{name:'第四章・城市之光',title:'直播間的最後一哩',desc:'帶著一路結識的朋友，讓這座城市看見阿志的新品牌。',need:120}];const places=[{id:'market',name:'逢甲夜市',x:28,y:32,person:'小桃',color:'#f5a4b5',desc:'霓虹招牌與人潮，適合接街頭委託。',talk:['你終於來啦！夜市需要人幫忙布置活動。','願意幫忙嗎？'],job:'夜市布置',gain:450,rep:12},{id:'garage',name:'海線車廠',x:72,y:70,person:'阿凱',color:'#82d8ee',desc:'改裝工坊，競速賽事從這裡開始。',talk:['這台車還能跑，但真正重要的是你的操控。','有空來試試我的新賽道！'],job:'試車與整理',gain:600,rep:14},{id:'temple',name:'老城廟埕',x:70,y:23,person:'阿嬤',color:'#f7ce87',desc:'安靜的廣場，能恢復行動力。',talk:['少年仔，走得快不如走得穩。','幫大家搬個桌椅，記得喝水。'],job:'廟埕志工',gain:180,rep:18},{id:'port',name:'台中港',x:19,y:76,person:'老船長',color:'#9ec6a7',desc:'海風與貨櫃，適合跑物流委託。',talk:['風吹過來就知道，今天適合出航。','願意幫忙整理貨單嗎？'],job:'港邊配送',gain:750,rep:11},{id:'studio',name:'直播工作室',x:49,y:52,person:'小晴',color:'#b6a5f6',desc:'為城市品牌錄製節目，提升知名度。',talk:['觀眾不只想看熱鬧，他們想聽故事。','把你這一路的經歷講給大家聽吧！'],job:'節目企劃',gain:520,rep:16}];const defaultState=()=>({money:1200,rep:0,energy:100,car:0,chapter:0,completed:[],visited:[],jobs:0,races:0,best:0,scene:'story',selected:'market',last:Date.now(),sound:true});let s=defaultState();try{let v=JSON.parse(localStorage.getItem(KEY));if(v)s={...s,...v}}catch(e){}s.energy=Math.min(100,s.energy+Math.floor((Date.now()-s.last)/60000)*3);let race=null,raf=0;const $=id=>document.getElementById(id);const money=n=>'$'+Math.floor(n).toLocaleString('en-US');function save(){s.last=Date.now();localStorage.setItem(KEY,JSON.stringify(s))}function beep(type='tap'){if(!s.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;const a=window._ac||(window._ac=new C());a.resume();let o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.type=type==='win'?'triangle':'sine';o.frequency.setValueAtTime(type==='win'?640:330,a.currentTime);o.frequency.exponentialRampToValueAtTime(type==='win'?960:470,a.currentTime+.12);g.gain.setValueAtTime(.08,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.19);o.start();o.stop(a.currentTime+.2)}catch(e){}}function toast(t){$('toast').textContent=t;$('toast').classList.remove('hidden');clearTimeout(window._toast);window._toast=setTimeout(()=>$('toast').classList.add('hidden'),2300)}function toggleSound(){s.sound=!s.sound;save();render()}const tabs=[['story','📖 主線故事'],['city','🗺️ 城市探索'],['race','🏁 街頭競速'],['garage','🚘 車庫'],['journal','🏆 冒險紀錄']];function nav(){return tabs.map(([id,n])=>`<button class="${s.scene===id?'active':''}" data-legacy-action="go('${id}')">${n}</button>`).join('')}function go(id){if(race&&id!=='race'){toast('比賽中，請先完成賽事');return}s.scene=id;save();render()}function refresh(){ $('money').textContent=money(s.money);$('rep').textContent=s.rep;$('energy').textContent=s.energy+'/100';$('car').textContent=['勁戰','改裝 DRG','C300'][s.car];$('chapterhead').textContent=chapters[s.chapter].name;$('soundbtn').textContent=s.sound?'🔊 音效':'🔇 靜音'}function render(){refresh();$('nav').innerHTML=nav();$('mobilemenu').innerHTML=nav();let title={story:'你的城市故事',city:'城市探索地圖',race:'海線競速挑戰',garage:'阿志車庫',journal:'冒險紀錄'};$('pagetitle').textContent=title[s.scene];({story:storyView,city:cityView,race:raceView,garage:garageView,journal:journalView})[s.scene]();}
function skyline(){return `<svg viewBox="0 0 1000 400" preserveAspectRatio="xMidYMid slice" role="img" aria-label="原創 2D 霓虹城市夜景"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#172447"/><stop offset="1" stop-color="#8b5277"/></linearGradient><linearGradient id="road" x2="0" y2="1"><stop stop-color="#34384f"/><stop offset="1" stop-color="#131b2b"/></linearGradient></defs><rect width="1000" height="400" fill="url(#sky)"/><circle cx="770" cy="76" r="38" fill="#fbd6a1"/><path d="M0 225L70 190 145 205 250 160 350 212 445 175 540 210 645 150 780 210 890 165 1000 195V400H0" fill="#293653"/><g fill="#17243b"><rect x="20" y="132" width="132" height="185"/><rect x="175" y="97" width="112" height="230"/><rect x="323" y="140" width="145" height="190"/><rect x="490" y="100" width="115" height="235"/><rect x="640" y="155" width="160" height="195"/><rect x="830" y="122" width="150" height="210"/></g><g fill="#ffcc80">${Array.from({length:45},(_,i)=>`<rect x="${35+(i*71)%930}" y="${160+(i*37)%130}" width="9" height="14" opacity="${i%4===0?.25:.85}"/>`).join('')}</g><path d="M0 322L1000 300V400H0" fill="url(#road)"/><path d="M0 350L1000 325" stroke="#fbd48e" stroke-width="4" stroke-dasharray="35 28"/><g transform="translate(395 230)"><ellipse cx="130" cy="104" rx="170" ry="23" fill="#0b1225" opacity=".65"/><path d="M20 60L60 16H205L252 55 275 66 270 97H0V77Z" fill="#e8a0b6" stroke="#ffe4cb" stroke-width="6"/><path d="M76 24H192L227 56H46Z" fill="#213653"/><circle cx="56" cy="98" r="26" fill="#151c2c" stroke="#c2d2df" stroke-width="8"/><circle cx="223" cy="98" r="26" fill="#151c2c" stroke="#c2d2df" stroke-width="8"/><rect x="4" y="69" width="29" height="12" rx="5" fill="#ffe1a6"/><rect x="251" y="70" width="22" height="10" fill="#ff5e7e"/></g></svg>`}
function face(color='#f4cba7'){return `<svg viewBox="0 0 100 100" role="img" aria-label="原創 2D 角色肖像"><rect width="100" height="100" fill="#273956"/><circle cx="50" cy="45" r="32" fill="${color}"/><path d="M17 40Q12 0 50 10Q85 1 83 40L75 24 29 25Z" fill="#24212c"/><path d="M21 90Q50 70 79 90V110H21Z" fill="#e3a47d"/><path d="M32 48h9m18 0h9" stroke="#222" stroke-width="4" stroke-linecap="round"/><path d="M44 65Q50 70 57 65" fill="none" stroke="#873e4c" stroke-width="3"/></svg>`}
function storyView(){let c=chapters[s.chapter],done=s.completed.includes(s.chapter),need=Math.max(0,c.need-s.rep);$('view').innerHTML=`<div class="hero">${skyline()}<div class="caption"><div class="kicker">${c.name}</div><h2>${c.title}</h2><p>${c.desc}</p></div></div><div class="section split"><div class="card"><div class="kicker">當前主線目標</div><h3>${done?'本章已完成':need?'累積 '+c.need+' 點街頭聲望':'可以推進劇情了'}</h3><p>${done?'前往下一章繼續旅程。':need?'探索城市並完成委託，還差 '+need+' 點聲望。':'準備好之後，點擊推進章節。'}</p><div class="progress"><div style="width:${Math.min(100,s.rep/Math.max(1,c.need)*100)}%"></div></div><div class="actions"><button class="btn primary" data-legacy-action="advance()" ${done||need?'disabled':''}>${s.chapter===3?'完成最終章':'推進主線 →'}</button><button class="btn" data-legacy-action="go('city')">前往探索</button></div></div><div class="card"><div class="kicker">下一步建議</div><h3>${s.chapter>=2?'到海線車廠挑戰賽事':'前往逢甲夜市'}</h3><p>每次只聚焦一個目標：探索地點、認識人物、完成委託，再回來推進故事。</p><button class="btn" data-legacy-action="go('${s.chapter>=2?'race':'city'}')">立即前往 →</button></div></div>`}function advance(){let c=chapters[s.chapter];if(s.rep<c.need||s.completed.includes(s.chapter))return;s.completed.push(s.chapter);s.money+=1000;beep('win');toast('章節完成！獎勵 $1,000');if(s.chapter<3)s.chapter++;save();render()}
function cityArt(){return `<svg viewBox="0 0 900 450" preserveAspectRatio="none" aria-label="手繪風格台中城市探索地圖"><rect width="900" height="450" fill="#1b3650"/><path d="M0 120Q160 40 300 150T600 100T900 120V0H0" fill="#264d5e"/><path d="M0 380Q200 290 350 390T900 330V450H0" fill="#1b5964"/><path d="M0 210L900 250M350 0L480 450M0 430L900 70" stroke="#8f8e86" stroke-width="52"/><path d="M0 210L900 250M350 0L480 450M0 430L900 70" stroke="#d4c6a4" stroke-width="38"/><path d="M0 210L900 250M350 0L480 450M0 430L900 70" stroke="#f6e2a6" stroke-width="2" stroke-dasharray="18 16"/><g fill="#38506b" stroke="#7898a1" stroke-width="3"><rect x="80" y="20" width="120" height="85" rx="8"/><rect x="570" y="40" width="145" height="90" rx="8"/><rect x="640" y="275" width="180" height="100" rx="8"/><rect x="95" y="290" width="160" height="120" rx="8"/><rect x="430" y="180" width="120" height="100" rx="8"/></g><g fill="#ffd580" opacity=".7">${Array.from({length:18},(_,i)=>`<rect x="${105+(i*37)%680}" y="${30+(i*51)%330}" width="9" height="10"/>`).join('')}</g></svg>`}function cityView(){let p=places.find(p=>p.id===s.selected);$('view').innerHTML=`<div class="map">${cityArt()}${places.map(p=>`<button class="mapnode ${s.selected===p.id?'sel':''}" style="left:${p.x}%;top:${p.y}%" data-legacy-action="selectPlace('${p.id}')">${p.name}${s.visited.includes(p.id)?' ✓':''}</button>`).join('')}</div><div class="section dialog"><div class="portrait">${face(p.color)}</div><div><strong>${p.person}｜${p.name}</strong><p>${p.desc}</p><div class="actions"><button class="btn primary" data-legacy-action="job()" ${s.energy<20?'disabled':''}>完成委託（20 ⚡）</button><button class="btn" data-legacy-action="talk()">與 ${p.person} 對話</button></div></div></div><div id="talkbox"></div><div class="notice mini">目前行動力 ${s.energy}/100｜委託可獲得資金與聲望；每分鐘恢復 3 點行動力。</div>`}function selectPlace(id){s.selected=id;beep();save();render()}function talk(){let p=places.find(p=>p.id===s.selected);$('talkbox').innerHTML=`<div class="section dialog"><div class="portrait">${face(p.color)}</div><div><strong>${p.person}</strong><p>「${p.talk[0]} ${p.talk[1]}」</p><button class="btn" data-legacy-action="$('talkbox').innerHTML=''">了解了</button></div></div>`}function job(){let p=places.find(p=>p.id===s.selected);if(s.energy<20)return;s.energy-=20;s.money+=p.gain;s.rep+=p.rep;s.jobs++;if(!s.visited.includes(p.id))s.visited.push(p.id);beep('win');toast(p.job+'完成！'+money(p.gain)+' / 聲望 +'+p.rep);save();render()}
function garageView(){let cars=[{name:'二手勁戰',price:0,speed:1,desc:'可靠的起點。'},{name:'改裝 DRG',price:3500,speed:1.3,desc:'競速里程加成 30%。'},{name:'外匯 C300',price:12000,speed:1.65,desc:'競速里程加成 65%。'}];$('view').innerHTML=`<div class="hero">${skyline()}<div class="caption"><h2>你的下一台座駕</h2><p>車輛不再只是數字倍率，而是直接影響競速表現。</p></div></div><div class="section cards">${cars.map((c,i)=>`<div class="card ${s.car===i?'selected':''}"><div class="kicker">車款 ${i+1}</div><h3>${c.name}</h3><p>${c.desc}</p><p>速度倍率 ×${c.speed}</p><button class="btn ${s.car===i?'':'primary'}" data-legacy-action="buyCar(${i})" ${i<=s.car||s.money<c.price?'disabled':''}>${i===s.car?'目前座駕':i<s.car?'已升級':money(c.price)+' 購買'}</button></div>`).join('')}</div>`}function buyCar(i){let costs=[0,3500,12000];if(i<=s.car||s.money<costs[i])return;s.money-=costs[i];s.car=i;beep('win');save();render()}
function raceView(){ $('view').innerHTML=`<div class="road"><canvas id="track" width="900" height="340"></canvas></div><div class="section split"><div class="card"><div class="kicker">海線競速</div><h3 id="racehud">準備起跑</h3><p>左右方向鍵 / A、D 或下方按鈕切換車道，閃避障礙。25 秒內挑戰最遠里程。</p><div class="actions"><button class="btn primary" data-legacy-action="startRace()" id="racego">開始比賽（10 ⚡）</button><button class="btn" data-legacy-action="steer(-1)">← 左移</button><button class="btn" data-legacy-action="steer(1)">右移 →</button></div></div><div class="card"><div class="kicker">競速紀錄</div><h3>最佳 ${s.best} 公尺</h3><p>完成場次 ${s.races}｜座駕：${['勁戰','改裝 DRG','C300'][s.car]}</p><div class="notice mini" id="raceresult">避開路障即可獲得更高的獎金與聲望。</div></div></div>`;drawTrack()}
function drawTrack(){let c=$('track');if(!c)return;let x=c.getContext('2d'),w=900,h=340;x.fillStyle='#1c3246';x.fillRect(0,0,w,h);x.fillStyle='#284f4c';x.fillRect(0,0,w,60);x.fillRect(0,280,w,60);x.fillStyle='#394254';x.fillRect(0,60,w,220);x.strokeStyle='#e6cb8d';x.lineWidth=3;x.setLineDash([30,22]);for(let y of [133,206]){x.beginPath();x.moveTo(0,y);x.lineTo(w,y);x.stroke()}x.setLineDash([]);let lane=race?race.lane:1;let cy=96+lane*73;x.fillStyle='#0c1524';x.beginPath();x.ellipse(180,cy+24,68,13,0,0,Math.PI*2);x.fill();x.fillStyle=['#f3a2bd','#8edee7','#f6ce80'][s.car];x.beginPath();x.roundRect(120,cy-22,125,43,13);x.fill();x.fillStyle='#24334a';x.fillRect(155,cy-16,50,30);x.fillStyle='#fff2b1';x.fillRect(231,cy-11,11,9);if(race)for(let o of race.obs){let oy=96+o.lane*73;x.fillStyle='#e99a65';x.beginPath();x.moveTo(o.x,oy-23);x.lineTo(o.x-20,oy+22);x.lineTo(o.x+20,oy+22);x.fill();x.fillStyle='#fff4ca';x.fillRect(o.x-11,oy+5,22,5)}}function startRace(){if(race||s.energy<10)return;s.energy-=10;save();race={lane:1,obs:[],distance:0,time:25,hp:3,spawn:0,last:performance.now()};$('racego').disabled=true;beep();raf=requestAnimationFrame(frame)}function steer(d){if(!race)return;race.lane=Math.max(0,Math.min(2,race.lane+d));drawTrack()}function frame(now){if(!race)return;let dt=Math.min(.05,(now-race.last)/1000);race.last=now;race.time-=dt;race.distance+=dt*45*[1,1.3,1.65][s.car];race.spawn+=dt;if(race.spawn>1.1){race.spawn=0;race.obs.push({x:930,lane:Math.floor(Math.random()*3),hit:false})}for(let o of race.obs){o.x-=dt*360;if(!o.hit&&o.x<240&&o.x>130&&o.lane===race.lane){o.hit=true;race.hp--;beep()}}race.obs=race.obs.filter(o=>o.x>-40);drawTrack();$('racehud').textContent=`${Math.ceil(race.time)} 秒｜${Math.floor(race.distance)} 公尺｜耐久 ${race.hp}/3`;if(race.time<=0||race.hp<=0){endRace();return}raf=requestAnimationFrame(frame)}function endRace(){if(!race)return;let dist=Math.floor(race.distance),gain=Math.floor(dist*(race.hp?1.2:.5)),reputation=Math.floor(dist/100);s.money+=gain;s.rep+=reputation;s.races++;s.best=Math.max(s.best,dist);race=null;save();beep('win');$('racego').disabled=false;$('racehud').textContent='比賽結束';$('raceresult').textContent=`完成 ${dist} 公尺｜獎金 ${money(gain)}｜聲望 +${reputation}`;refresh()}
window.addEventListener('keydown',e=>{if(!race)return;if(['ArrowLeft','a','A'].includes(e.key)){e.preventDefault();steer(-1)}if(['ArrowRight','d','D'].includes(e.key)){e.preventDefault();steer(1)}});function journalView(){$('view').innerHTML=`<div class="cards"><div class="card"><div class="kicker">探索進度</div><h2>${s.visited.length}/5</h2><p>已造訪地點</p></div><div class="card"><div class="kicker">完成委託</div><h2>${s.jobs}</h2><p>一步一腳印的城市工作</p></div><div class="card"><div class="kicker">街頭競速</div><h2>${s.races}</h2><p>最佳 ${s.best} 公尺</p></div><div class="card"><div class="kicker">故事篇章</div><h2>${s.completed.length}/4</h2><p>已完成的章節</p></div></div><div class="section card"><h3>成長路線</h3><p>以城市委託賺取資金和聲望，購買更好的車、挑戰競速，逐章完成阿志的轉型故事。</p><button class="btn" data-legacy-action="exportSave()">匯出存檔 JSON</button> <button class="btn" data-legacy-action="resetSave()">重新開始</button></div>`}function exportSave(){let b=new Blob([JSON.stringify(s,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='阿志6_存檔.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}function resetSave(){if(!confirm('確定要清除 6.0 存檔，重新開始嗎？'))return;localStorage.removeItem(KEY);s=defaultState();render()}setInterval(()=>{if(s.energy<100){s.energy=Math.min(100,s.energy+3);save();refresh()}},60000);render();

// 6.1: focused campaign, branching dialogue and meaningful chapter gates.
const QUESTS=[
 {title:'認識夜市的夥伴',detail:'前往逢甲夜市，與小桃對話並完成一次委託。',place:'market',goal:()=>s.visited.includes('market')&&(s.relationships?.market||0)>0},
 {title:'打造你的第一台改裝車',detail:'與海線車廠的阿凱聊聊，升級為改裝 DRG。',place:'garage',goal:()=>s.car>=1&&(s.relationships?.garage||0)>0},
 {title:'跑出自己的名聲',detail:'完成一場街頭競速，並在台中港接下一份委託。',place:'port',goal:()=>s.races>=1&&s.visited.includes('port')},
 {title:'讓城市聽見你的故事',detail:'與直播工作室的小晴建立信任，並造訪老城廟埕。',place:'studio',goal:()=> (s.relationships?.studio||0)>0&&s.visited.includes('temple')}
];
const DIALOGUES={
 market:[['小桃','你想在這裡做生意？先別急著談錢。逢甲的客人，最在乎的是誠意。'],['小桃','今晚攤商忙不過來。你願意幫忙布置嗎？']],
 garage:[['阿凱','引擎很大聲，不代表你開得快。你要學的是判斷，不是逞強。'],['阿凱','如果你願意先把車整理好，我就教你跑海線的彎。']],
 temple:[['阿嬤','少年仔，路是自己選的。慢慢走，也能走得遠。'],['阿嬤','廟埕今天缺人手，你要不要來幫忙？']],
 port:[['老船長','貨櫃一箱一箱搬，人生也是一站一站走。'],['老船長','今天這批貨需要幫忙整理，敢不敢接？']],
 studio:[['小晴','直播不是喊得大聲就有人相信。你有沒有真正想說的故事？'],['小晴','講講你為什麼想重新開始吧。']]
};
if(!s.relationships)s.relationships={};if(!s.dialogueFlags)s.dialogueFlags={};
function objective(){return QUESTS[Math.min(s.chapter,3)]}
function objectiveBox(){let q=objective(),ok=q.goal();return `<div class="questline"><div><div class="kicker">🎯 當前唯一主線任務</div><strong>${q.title}</strong><p>${q.detail}</p><div class="mood"><span>${ok?'✓ 目標達成':'○ 尚未完成'}</span><span>第 ${s.chapter+1} / 4 章</span></div></div><button class="btn ${ok?'primary':''}" data-legacy-action="${ok?'go(\'story\')':`go('${s.chapter===2?'race':'city'}')`}">${ok?'回主線領獎':'開始任務 →'}</button></div>`}
storyView=function(){let c=chapters[s.chapter],ok=objective().goal(),done=s.completed.includes(s.chapter);$('view').innerHTML=`<div class="hero">${skyline()}<span class="arttag">ORIGINAL VECTOR ART · 6.1</span><div class="caption"><div class="kicker">${c.name}</div><h2>${c.title}</h2><p>${c.desc}</p></div></div>${objectiveBox()}<div class="split"><div class="card"><div class="kicker">劇情進度</div><h3>${done?'已完成本章':ok?'可以推進劇情':'先完成當前目標'}</h3><p>章節任務完成後，解鎖下一段故事與獎勵。聲望不再是唯一通關條件。</p><div class="actions"><button class="btn primary" data-legacy-action="advance()" ${done||!ok?'disabled':''}>${s.chapter===3?'完成最終章':'完成本章 →'}</button></div></div><div class="card"><div class="kicker">旅程紀錄</div><h3>${s.completed.length} / 4 章</h3><p>你認識了 ${Object.keys(s.relationships||{}).length} 位城市夥伴，完成 ${s.jobs} 份委託。</p><button class="btn" data-legacy-action="go('journal')">查看旅程</button></div></div>`};
advance=function(){if(!objective().goal()||s.completed.includes(s.chapter))return;s.completed.push(s.chapter);s.money+=1000;beep('win');toast('章節完成！獎勵 $1,000');if(s.chapter<3)s.chapter++;save();render()};
cityView=function(){let p=places.find(p=>p.id===s.selected),rel=s.relationships[p.id]||0;$('view').innerHTML=`${objectiveBox()}<div class="map">${cityArt()}${places.map(p=>`<button class="mapnode ${s.selected===p.id?'sel':''}" style="left:${p.x}%;top:${p.y}%" data-legacy-action="selectPlace('${p.id}')">${p.name}${s.visited.includes(p.id)?' ✓':''}</button>`).join('')}</div><div class="section dialog"><div class="portrait">${face(p.color)}</div><div><strong>${p.person}｜${p.name}</strong><p>${p.desc}</p><div class="mood"><span>好感度 ${rel}</span><span>委託報酬 ${money(p.gain)}</span></div><div class="actions"><button class="btn primary" data-legacy-action="talk()">與 ${p.person} 對話</button><button class="btn" data-legacy-action="job()" ${s.energy<20?'disabled':''}>完成委託（20 ⚡）</button></div></div></div><div id="talkbox"></div><div class="notice mini">探索提示：對話選擇會影響 NPC 好感度；完成委託可賺取升級車輛的資金。</div>`};
talk=function(){let p=places.find(p=>p.id===s.selected),dialog=DIALOGUES[p.id],first=!(s.dialogueFlags[p.id]);$('talkbox').innerHTML=`<div class="storypanel"><div class="speaker">${p.person} · ${first?'初次相遇':'再次見面'}</div><p>「${first?dialog[0][1]:dialog[1][1]}」</p><div class="choices"><button class="btn primary" data-legacy-action="dialogChoice('help')">我願意幫忙，先從小事做起。</button><button class="btn" data-legacy-action="dialogChoice('listen')">我想先聽聽你的故事。</button></div></div>`};
function dialogChoice(kind){let p=places.find(p=>p.id===s.selected),delta=kind==='help'?2:1;s.relationships[p.id]=(s.relationships[p.id]||0)+delta;s.dialogueFlags[p.id]=true;let line=kind==='help'?'謝謝你。這座城市會記得願意付出的人。':'不急，我們慢慢聊。每個人都有自己的故事。';$('talkbox').innerHTML=`<div class="storypanel"><div class="speaker">${p.person}</div><p>「${line}」</p><div class="mood"><span>好感度 +${delta}</span></div><button class="btn" data-legacy-action="$('talkbox').innerHTML=''">結束對話</button></div>`;beep('win');save();refresh()}
// More legible road scene, feedback on damage and short racing objective.
const originalEndRace=endRace;endRace=function(){let before=s.races;originalEndRace();if(s.races>before){toast('競速完成！回主線查看進度');}}
const originalJournal=journalView;journalView=function(){originalJournal();let container=$('view');container.insertAdjacentHTML('afterbegin',`<div class="card"><div class="kicker">故事目標</div><h3>${objective().title}</h3><p>${objective().detail}</p><div class="mood"><span>${objective().goal()?'✓ 已達成':'進行中'}</span><span>已結識 ${Object.keys(s.relationships||{}).length} 位夥伴</span></div></div>`)};
render();

// 6.3 - 即時街頭競技場：原創虛構訓練對戰，不涉及現實暴力操作指引。
const oldTabsCombat=tabs.slice();tabs.splice(3,0,['combat','⚔️ 即時對戰']);
const oldRenderCombat=render;render=function(){if(s.scene==='combat'){refresh();$('nav').innerHTML=nav();$('mobilemenu').innerHTML=nav();$('pagetitle').textContent='海線街頭競技場';combatView();return}oldRenderCombat()};
const oldGoCombat=go;go=function(id){if(battle&&battle.running&&id!=='combat'){toast('對戰進行中，請先結束挑戰');return}oldGoCombat(id)};
s.battleWins=s.battleWins||0;s.battleBest=s.battleBest||0;
let battle=null,combatRAF=0,combatKeys=new Set(),combatLast=0;
function combatView(){
 $('view').innerHTML=`<div class="card"><div class="kicker">支線挑戰・虛構街頭競技</div><h2>海線擂台：霓虹生存戰</h2><p>即時移動、閃避敵人、近距離攻擊，連續擊退挑戰者。每次挑戰消耗 15 點行動力，獲得獎金與聲望。</p><div class="combat-hud"><span class="combat-chip" id="cwave">波次 1</span><span class="combat-chip" id="cscore">分數 0</span><span class="combat-chip" id="ctime">時間 60 秒</span></div><div class="combat-bar"><div id="chp" style="width:100%"></div></div><div class="combat-stage"><canvas id="combatCanvas" width="800" height="420" aria-label="即時戰鬥場景"></canvas><div class="combat-overlay" id="combatOverlay"><h2>準備上場？</h2><p>方向鍵 / WASD 移動，空白鍵攻擊，Shift 閃避。手機可使用下方按鈕。</p><button class="btn primary" data-legacy-action="startCombat()">開始挑戰（15 ⚡）</button></div></div><div class="combat-controls"><div><button class="btn" data-combat="ArrowLeft">←</button><button class="btn" data-combat="ArrowUp">↑</button><button class="btn" data-combat="ArrowDown">↓</button><button class="btn" data-combat="ArrowRight">→</button></div><div><button class="btn primary" data-legacy-action="combatAttack()">攻擊</button> <button class="btn" data-legacy-action="combatDodge()">閃避</button></div></div><div class="combat-tip">攻擊有冷卻時間；閃避期間短暫無敵。敵人逐波增加，血量耗盡或倒數結束即結算。</div><div class="card"><b>最佳分數：${s.battleBest}</b>　｜　累計勝場：${s.battleWins}</div></div>`;
 document.querySelectorAll('[data-combat]').forEach(b=>{let k=b.dataset.combat;b.addEventListener('pointerdown',e=>{e.preventDefault();combatKeys.add(k);b.setPointerCapture(e.pointerId)});for(let ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>combatKeys.delete(k))});
 drawCombat();
}
function startCombat(){if(battle||s.energy<15){if(!battle)toast('行動力不足');return}s.energy-=15;save();battle={running:true,t:60,score:0,kills:0,wave:1,spawn:0,player:{x:400,y:210,hp:100,face:1,atk:0,dodge:0,inv:0},enemies:[],effects:[]};$('combatOverlay').classList.add('hidden');combatLast=performance.now();combatRAF=requestAnimationFrame(combatFrame);refresh()}
function combatAttack(){if(!battle||!battle.running)return;let p=battle.player;if(p.atk>0)return;p.atk=.38;beep();let hit=0;for(let e of battle.enemies){let dx=e.x-p.x,dy=e.y-p.y;if(Math.hypot(dx,dy)<92&&(Math.abs(dx)<35||Math.sign(dx)===p.face)){e.hp-=1;hit++;e.x+=p.face*24;battle.effects.push({x:e.x,y:e.y,t:.3})}}if(hit)battle.score+=hit*10}
function combatDodge(){if(!battle||!battle.running)return;let p=battle.player;if(p.dodge>0||p.inv>0)return;p.dodge=1.5;p.inv=.48;p.x=Math.max(32,Math.min(768,p.x+p.face*85));beep()}
function combatFrame(now){if(!battle||!battle.running)return;let dt=Math.min(.04,(now-combatLast)/1000);combatLast=now;let b=battle,p=b.player;b.t-=dt;p.atk=Math.max(0,p.atk-dt);p.dodge=Math.max(0,p.dodge-dt);p.inv=Math.max(0,p.inv-dt);let dx=Number(combatKeys.has('ArrowRight')||combatKeys.has('d'))-Number(combatKeys.has('ArrowLeft')||combatKeys.has('a'));let dy=Number(combatKeys.has('ArrowDown')||combatKeys.has('s'))-Number(combatKeys.has('ArrowUp')||combatKeys.has('w'));let norm=Math.hypot(dx,dy)||1;p.x=Math.max(28,Math.min(772,p.x+dx/norm*205*dt));p.y=Math.max(75,Math.min(382,p.y+dy/norm*205*dt));if(dx)p.face=Math.sign(dx);b.wave=1+Math.floor(b.kills/5);b.spawn+=dt;if(b.spawn>Math.max(.65,2.0-b.wave*.15)&&b.enemies.length<12){b.spawn=0;let edge=Math.random()<.5?25:775;b.enemies.push({x:edge,y:95+Math.random()*265,hp:b.wave>3?3:2,cd:0,speed:52+b.wave*9})}
 for(let e of b.enemies){e.cd=Math.max(0,e.cd-dt);let vx=p.x-e.x,vy=p.y-e.y,dist=Math.hypot(vx,vy)||1;if(dist>37){e.x+=vx/dist*e.speed*dt;e.y+=vy/dist*e.speed*dt}else if(!e.cd){e.cd=1.2;if(!p.inv){p.hp-=9;p.inv=.55;beep()}}}
 b.enemies=b.enemies.filter(e=>{if(e.hp>0)return true;b.kills++;b.score+=100;return false});b.effects=b.effects.filter(e=>(e.t-=dt)>0);drawCombat();$('cwave').textContent='波次 '+b.wave;$('cscore').textContent='分數 '+b.score;$('ctime').textContent='時間 '+Math.ceil(Math.max(0,b.t))+' 秒';$('chp').style.width=Math.max(0,p.hp)+'%';if(p.hp<=0||b.t<=0){finishCombat();return}combatRAF=requestAnimationFrame(combatFrame)}
function drawCombat(){let c=$('combatCanvas');if(!c)return;let x=c.getContext('2d'),b=battle;x.clearRect(0,0,800,420);let grad=x.createLinearGradient(0,0,0,420);grad.addColorStop(0,'#273e62');grad.addColorStop(1,'#10182e');x.fillStyle=grad;x.fillRect(0,0,800,420);x.fillStyle='#16253e';for(let i=0;i<12;i++){x.fillRect(i*74,25,52,95+(i%3)*16);x.fillStyle='#ffd68a';x.fillRect(i*74+12,50,12,15);x.fillStyle='#16253e'}x.fillStyle='#26384d';x.fillRect(0,105,800,315);x.strokeStyle='#526581';x.lineWidth=2;for(let i=0;i<8;i++){x.beginPath();x.moveTo(i*110,110);x.lineTo(i*110,420);x.stroke()}for(let j=0;j<4;j++){x.beginPath();x.moveTo(0,150+j*75);x.lineTo(800,150+j*75);x.stroke()}
 const drawPerson=(p,enemy=false)=>{x.save();x.translate(p.x,p.y);if(!enemy&&p.inv>0&&Math.floor(p.inv*15)%2)x.globalAlpha=.4;x.fillStyle='#0c1728';x.beginPath();x.ellipse(0,24,24,8,0,0,Math.PI*2);x.fill();x.fillStyle=enemy?'#ed7c91':'#8ce0dc';x.fillRect(-15,-18,30,39);x.fillStyle=enemy?'#edb5a3':'#f0c6a3';x.beginPath();x.arc(0,-28,15,0,Math.PI*2);x.fill();x.fillStyle='#1b2134';x.beginPath();x.arc(0,-35,16,Math.PI,Math.PI*2);x.fill();x.fillStyle='#192039';x.fillRect(-12,21,9,17);x.fillRect(4,21,9,17);if(!enemy){x.strokeStyle='#ffd47c';x.lineWidth=4;x.beginPath();x.arc(0,-9,12,0,Math.PI);x.stroke();if(p.atk>0.15){x.strokeStyle='#f8e0a4';x.lineWidth=8;x.beginPath();x.arc(p.face*28,-5,43,-1.1,1.1);x.stroke()}}else{x.fillStyle='#1a1c29';x.fillRect(-10,-28,7,3);x.fillRect(4,-28,7,3)}x.restore()};if(b){b.enemies.forEach(e=>drawPerson(e,true));drawPerson(b.player);for(let ef of b.effects){x.strokeStyle='#ffe28e';x.lineWidth=4;x.beginPath();x.arc(ef.x,ef.y,30*(1-ef.t)+8,0,Math.PI*2);x.stroke()}}else{drawPerson({x:400,y:230,atk:0,inv:0,face:1})}}
function finishCombat(){if(!battle)return;cancelAnimationFrame(combatRAF);let b=battle;b.running=false;let prize=Math.floor(b.score*.45),rep=Math.floor(b.kills*2);s.money+=prize;s.rep+=rep;s.battleBest=Math.max(s.battleBest,b.score);if(b.kills>=5)s.battleWins++;save();refresh();$('combatOverlay').classList.remove('hidden');$('combatOverlay').innerHTML=`<h2>${b.kills>=5?'挑戰成功！':'挑戰結束'}</h2><p>擊退 ${b.kills} 名挑戰者｜分數 ${b.score}<br>獎金 ${money(prize)}｜聲望 +${rep}</p><button class="btn primary" data-legacy-action="battle=null;combatView()">再挑戰一次</button><button class="btn" data-legacy-action="battle=null;go('story')">返回主線</button>`;beep('win')}
window.addEventListener('keydown',e=>{if(!battle||!battle.running)return;let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' ','shift','w','a','s','d'].includes(k))e.preventDefault();if(e.key===' ')combatAttack();else if(e.key==='Shift')combatDodge();else combatKeys.add(e.key.length===1?k:e.key)});
window.addEventListener('keyup',e=>combatKeys.delete(e.key.length===1?e.key.toLowerCase():e.key));window.addEventListener('blur',()=>combatKeys.clear());
const oldJournalCombat=journalView;journalView=function(){oldJournalCombat();$('view').insertAdjacentHTML('beforeend',`<div class="card"><h3>⚔️ 即時對戰紀錄</h3><p>最佳分數 ${s.battleBest||0}｜成功挑戰 ${s.battleWins||0} 場</p><button class="btn" data-legacy-action="go('combat')">前往擂台</button></div>`)};

// 6.3 — 原創街機一對一格鬥
const fighterStyle=document.createElement('style');fighterStyle.textContent=`
.fight-shell{display:grid;gap:14px}.fight-hud{display:grid;grid-template-columns:1fr auto 1fr;gap:12px;align-items:center}.fight-life{height:18px;background:#1b263b;border:2px solid #fff5;border-radius:7px;overflow:hidden}.fight-life>div{height:100%;background:linear-gradient(90deg,#f2ae67,#ff547f);transition:width .1s}.fight-life.enemy>div{background:linear-gradient(90deg,#78e5d4,#5e9cf5)}.fight-stat{display:flex;justify-content:space-between;font-weight:800;margin-bottom:5px}.fight-arena{position:relative;overflow:hidden;border:3px solid #78d8e4;border-radius:15px;box-shadow:0 12px 40px #070c20aa}.fight-arena canvas{display:block;width:100%;aspect-ratio:16/9;touch-action:none}.fight-mask{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;background:#10192bc9;text-align:center;padding:18px;gap:12px}.fight-mask.hidden{display:none}.fight-mask h2{color:#fff;margin:0}.fight-mask p{max-width:440px}.fight-pad{display:grid;grid-template-columns:1fr 1fr;gap:12px}.fight-pad>div{display:flex;flex-wrap:wrap;gap:7px;align-items:center}.fight-pad button{min-width:57px;min-height:47px;touch-action:none;user-select:none}.fight-pad button:active{transform:scale(.94);filter:brightness(1.3)}.fight-instructions{font-size:13px;opacity:.82}.fight-special{height:9px;background:#26334d;border-radius:8px;overflow:hidden}.fight-special>div{height:100%;background:linear-gradient(90deg,#a975ff,#ffe08d)}@media(max-width:650px){.fight-pad{grid-template-columns:1fr}.fight-hud{gap:5px}.fight-pad>div{justify-content:center}.fight-pad button{flex:1}.fight-stat{font-size:12px}}
`;document.head.appendChild(fighterStyle);
tabs.splice(4,0,['fighter','🥊 格鬥大會']);
s.fighterWins=s.fighterWins||0;s.fighterLosses=s.fighterLosses||0;
let fg=null,fgRAF=0,fgLast=0,fgKeys=new Set();
const fighterOldRender=render;render=function(){if(s.scene==='fighter'){refresh();$('nav').innerHTML=nav();$('mobilemenu').innerHTML=nav();$('pagetitle').textContent='霓虹格鬥大會';fighterView();return}fighterOldRender()};
const fighterOldGo=go;go=function(id){if(fg&&fg.running&&id!=='fighter'){toast('格鬥進行中，請先完成對戰');return}fighterOldGo(id)};
function fighterView(){
 $('view').innerHTML=`<div class="fight-shell"><div class="card"><div class="kicker">原創 2D 街機格鬥｜單人 VS CPU</div><h2>🥊 霓虹格鬥大會</h2><p>一對一、三戰兩勝。拳腳連段、防禦、跳躍、氣功波與必殺技！勝利可獲得資金與聲望。</p></div><div class="fight-hud"><div><div class="fight-stat"><span>阿志</span><span id="fgPText">100</span></div><div class="fight-life"><div id="fgPHP" style="width:100%"></div></div><div class="fight-special"><div id="fgMeter" style="width:0%"></div></div></div><div style="text-align:center"><b id="fgTime" style="font-size:27px">60</b><div id="fgRound" style="font-size:12px">ROUND 1</div><div id="fgScore" style="font-size:12px">○ ○ : ○ ○</div></div><div><div class="fight-stat"><span>海線拳王</span><span id="fgEText">100</span></div><div class="fight-life enemy"><div id="fgEHP" style="width:100%"></div></div><div class="fight-special"><div style="width:45%"></div></div></div></div><div class="fight-arena"><canvas id="fighterCanvas" width="960" height="540" aria-label="2D 一對一格鬥場景"></canvas><div class="fight-mask" id="fgMask"><h2>準備開打！</h2><p>方向鍵移動／跳躍／蹲下，J 輕拳、K 重拳、L 防禦、U 氣功波、I 必殺技。</p><button class="btn primary" data-legacy-action="startFighter()">開始三戰兩勝（10 ⚡）</button></div></div><div class="fight-pad"><div><button class="btn" data-fg="ArrowLeft">◀</button><button class="btn" data-fg="ArrowDown">▼</button><button class="btn" data-fg="ArrowUp">▲</button><button class="btn" data-fg="ArrowRight">▶</button></div><div><button class="btn primary" data-fg="j">輕拳 J</button><button class="btn primary" data-fg="k">重拳 K</button><button class="btn" data-fg="l">防禦 L</button><button class="btn" data-fg="u">氣功 U</button><button class="btn" data-fg="i">必殺 I</button></div></div><div class="fight-instructions">💡 近身連續出拳可以增加能量；防禦能減少傷害。氣功消耗 35 能量，必殺技消耗 75 能量。最佳策略是抓準距離與出招時機。</div><div class="card">🏆 累計勝場 <b>${s.fighterWins}</b>　｜　落敗 <b>${s.fighterLosses}</b></div></div>`;
 document.querySelectorAll('[data-fg]').forEach(b=>{const k=b.dataset.fg;const down=e=>{e.preventDefault();fgKeys.add(k);b.setPointerCapture?.(e.pointerId)};b.addEventListener('pointerdown',down);['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>fgKeys.delete(k)))});if(fg)drawFighter();else drawFighterPreview();
}
function drawFighterPreview(){const c=$('fighterCanvas');if(!c)return;let ctx=c.getContext('2d');drawFightStage(ctx,0);drawFighterPerson(ctx,{x:300,y:435,face:1,hp:100,action:'idle',anim:0},false);drawFighterPerson(ctx,{x:670,y:435,face:-1,hp:100,action:'idle',anim:0},true)}
function newFighter(x,face){return {x,y:435,vy:0,face,hp:100,meter:0,cd:0,stun:0,action:'idle',anim:0,guard:false,combo:0}}
function startFighter(){if(fg?.running||s.energy<10){if(s.energy<10)toast('行動力不足');return}s.energy-=10;save();fg={running:true,p:newFighter(250,1),e:newFighter(710,-1),round:1,pWins:0,eWins:0,t:60,shots:[],sparks:[],aiTimer:0,aiDecision:'approach',notice:'ROUND 1',noticeTime:1.2};$('fgMask').classList.add('hidden');fgLast=performance.now();fgRAF=requestAnimationFrame(fighterLoop);refresh()}
function fighterAttack(who,type){if(!fg?.running||who.cd>0||who.stun>0)return;const heavy=type==='heavy',special=type==='special',ultimate=type==='ultimate';let cost=special?35:ultimate?75:0;if(who.meter<cost)return;who.meter-=cost;who.action=type;who.anim=heavy?.32:ultimate?.58:.22;who.cd=heavy?.62:ultimate?.95:special?.7:.32;const foe=who===fg.p?fg.e:fg.p;if(special||ultimate){fg.shots.push({x:who.x+who.face*52,y:who.y-80,face:who.face,owner:who,damage:ultimate?29:14,life:1.5,r:ultimate?31:18});fg.sparks.push({x:who.x+who.face*60,y:who.y-75,life:.25,size:36});beep('win');return}const dist=Math.abs(foe.x-who.x);if(dist<(heavy?145:115)&&Math.abs(foe.y-who.y)<55&&Math.sign(foe.x-who.x)===who.face){fighterHit(foe,heavy?15:7,who);who.meter=Math.min(100,who.meter+(heavy?13:8));fg.sparks.push({x:foe.x,y:foe.y-80,life:.24,size:heavy?35:22})}beep()}
function fighterHit(target,dmg,source){const blocked=target.guard&&Math.sign(source.x-target.x)===target.face;const amount=blocked?Math.max(1,Math.floor(dmg*.18)):dmg;target.hp=Math.max(0,target.hp-amount);target.stun=blocked?.10:.22;target.action=blocked?'guard':'hurt';target.anim=.23;target.x=Math.max(65,Math.min(895,target.x+(target.x>source.x?1:-1)*(blocked?8:23)));target.meter=Math.min(100,target.meter+5);if(target.hp<=0)endFighterRound()}
function fighterLoop(now){if(!fg?.running)return;let dt=Math.min(.033,(now-fgLast)/1000);fgLast=now;const g=fg,p=g.p,e=g.e;g.t-=dt;for(let q of [p,e]){q.cd=Math.max(0,q.cd-dt);q.stun=Math.max(0,q.stun-dt);q.anim=Math.max(0,q.anim-dt);q.face=q===p?(p.x<e.x?1:-1):(e.x<p.x?1:-1);if(q.anim<=0)q.action='idle';q.vy+=1700*dt;q.y=Math.min(435,q.y+q.vy*dt);if(q.y===435)q.vy=0}p.guard=fgKeys.has('l')&&p.y===435;if(p.guard)p.action='guard';if(!p.stun){let m=(fgKeys.has('ArrowRight')?1:0)-(fgKeys.has('ArrowLeft')?1:0);p.x=Math.max(55,Math.min(905,p.x+m*260*dt));if(fgKeys.has('ArrowUp')&&p.y===435){p.vy=-650;p.action='jump'}if(fgKeys.has('j')){fgKeys.delete('j');fighterAttack(p,'light')}if(fgKeys.has('k')){fgKeys.delete('k');fighterAttack(p,'heavy')}if(fgKeys.has('u')){fgKeys.delete('u');fighterAttack(p,'special')}if(fgKeys.has('i')){fgKeys.delete('i');fighterAttack(p,'ultimate')}}
 g.aiTimer-=dt;if(g.aiTimer<=0){g.aiTimer=.26+Math.random()*.36;let dist=Math.abs(p.x-e.x);e.guard=Math.random()<.17&&dist<155;if(!e.stun){if(dist>125)e.x+=e.face*(65+g.round*13)*g.aiTimer;else if(dist<60&&Math.random()<.3)e.x-=e.face*35;if(dist<155&&Math.random()<.64)fighterAttack(e,Math.random()<.35?'heavy':'light');else if(dist>200&&e.meter>=35&&Math.random()<.28)fighterAttack(e,'special')}}e.x=Math.max(55,Math.min(905,e.x));
 for(const sh of g.shots){sh.x+=sh.face*480*dt;sh.life-=dt;let target=sh.owner===p?e:p;if(Math.abs(sh.x-target.x)<sh.r+23&&Math.abs(sh.y-(target.y-80))<62){fighterHit(target,sh.damage,sh.owner);sh.life=0;g.sparks.push({x:target.x,y:target.y-80,life:.28,size:sh.r+20})}}g.shots=g.shots.filter(sh=>sh.life>0&&sh.x>-30&&sh.x<990);g.sparks=g.sparks.filter(sp=>(sp.life-=dt)>0);if(g.noticeTime>0)g.noticeTime-=dt;drawFighter();updateFighterHud();if(g.t<=0)endFighterRound();if(fg?.running)fgRAF=requestAnimationFrame(fighterLoop)}
function endFighterRound(){if(!fg?.running)return;let g=fg;g.running=false;cancelAnimationFrame(fgRAF);const won=g.p.hp>=g.e.hp;if(won)g.pWins++;else g.eWins++;const matchOver=g.pWins===2||g.eWins===2;if(matchOver){const victory=g.pWins===2;const reward=victory?1800:250,rep=victory?22:3;s.money+=reward;s.rep+=rep;if(victory)s.fighterWins++;else s.fighterLosses++;save();refresh();$('fgMask').classList.remove('hidden');$('fgMask').innerHTML=`<h2>${victory?'🏆 阿志勝出！':'再接再厲！'}</h2><p>對戰結果 ${g.pWins} : ${g.eWins}<br>獎金 ${money(reward)}｜聲望 +${rep}</p><button class="btn primary" data-legacy-action="fg=null;fighterView()">再次挑戰</button><button class="btn" data-legacy-action="fg=null;go('story')">返回主線</button>`;beep('win');return}g.round++;g.t=60;g.p=newFighter(250,1);g.e=newFighter(710,-1);g.shots=[];g.sparks=[];g.aiTimer=1;g.notice='ROUND '+g.round;g.noticeTime=1.3;g.running=true;fgLast=performance.now();fgRAF=requestAnimationFrame(fighterLoop)}
function updateFighterHud(){if(!fg)return;let g=fg;const set=(id,t)=>{const el=$(id);if(el)el.textContent=t};const width=(id,n)=>{const el=$(id);if(el)el.style.width=Math.max(0,n)+'%'};set('fgPText',Math.ceil(g.p.hp));set('fgEText',Math.ceil(g.e.hp));set('fgTime',Math.max(0,Math.ceil(g.t)));set('fgRound','ROUND '+g.round);set('fgScore',`${'● '.repeat(g.pWins)}${'○ '.repeat(2-g.pWins)} : ${'● '.repeat(g.eWins)}${'○ '.repeat(2-g.eWins)}`);width('fgPHP',g.p.hp);width('fgEHP',g.e.hp);width('fgMeter',g.p.meter)}
function drawFightStage(c,t){const sky=c.createLinearGradient(0,0,0,540);sky.addColorStop(0,'#121a42');sky.addColorStop(.65,'#563d77');sky.addColorStop(1,'#dc7795');c.fillStyle=sky;c.fillRect(0,0,960,540);c.fillStyle='#f9cf9a';c.beginPath();c.arc(790,112,48,0,7);c.fill();for(let i=0;i<18;i++){let h=110+(i*61)%150;c.fillStyle=i%2?'#1b264b':'#24345c';c.fillRect(i*58,295-h,60,h+120);c.fillStyle='#ffd58d';for(let j=0;j<4;j++)c.fillRect(i*58+12+(j%2)*22,310-h+Math.floor(j/2)*34,9,14)}c.fillStyle='#202a49';c.fillRect(0,368,960,172);c.fillStyle='#394462';c.fillRect(0,412,960,128);c.strokeStyle='#f5b8b9';c.lineWidth=3;c.beginPath();c.moveTo(0,420);c.lineTo(960,420);c.stroke();c.strokeStyle='#7182a1';for(let i=0;i<8;i++){c.beginPath();c.moveTo(480,415);c.lineTo(i*155-70,540);c.stroke()}c.fillStyle='#ffdc8e';c.font='bold 24px sans-serif';c.fillText('NEON FIGHT • 海線擂台',28,58)}
function drawFighterPerson(c,q,enemy){c.save();c.translate(q.x,q.y);c.scale(q.face,1);if(q.action==='hurt')c.globalAlpha=.68;c.fillStyle='#0a1426aa';c.beginPath();c.ellipse(0,7,43,12,0,0,7);c.fill();let bob=q.y<435?0:Math.sin(performance.now()/160)*2;c.translate(0,bob);c.fillStyle=enemy?'#284f76':'#2e284d';c.fillRect(-23,-68,17,70);c.fillRect(7,-68,17,70);c.fillStyle=enemy?'#52c8e8':'#f6a4b9';c.beginPath();c.roundRect(-30,-132,60,73,12);c.fill();c.fillStyle='#f4bd9b';c.beginPath();c.arc(0,-155,29,0,7);c.fill();c.fillStyle=enemy?'#273349':'#211d31';c.beginPath();c.arc(0,-168,30,Math.PI,Math.PI*2);c.lineTo(30,-156);c.lineTo(-28,-155);c.fill();c.fillStyle='#21222d';c.fillRect(8,-157,5,4);c.fillStyle='#f4bd9b';let punch=q.action==='light'||q.action==='heavy'||q.action==='special'||q.action==='ultimate';let reach=punch?65:23;c.save();c.translate(22,-117);c.rotate(punch?-.1:.35);c.fillRect(0,0,reach,15);c.fillStyle=enemy?'#e2f7fc':'#fff1d5';c.beginPath();c.arc(reach,8,punch?15:11,0,7);c.fill();c.restore();c.fillStyle='#f4bd9b';c.fillRect(-42,-113,20,55);if(q.guard){c.strokeStyle='#c9e7ff';c.lineWidth=5;c.beginPath();c.arc(0,-100,62,-1.5,1.2);c.stroke()}if(!enemy){c.strokeStyle='#ffdc7a';c.lineWidth=4;c.beginPath();c.arc(0,-105,20,0,Math.PI);c.stroke()}c.restore()}
function drawFighter(){const canvas=$('fighterCanvas');if(!canvas||!fg)return;const c=canvas.getContext('2d'),g=fg;drawFightStage(c,g.t);drawFighterPerson(c,g.p,false);drawFighterPerson(c,g.e,true);for(const sh of g.shots){c.fillStyle=sh.owner===g.p?'#ffdc85':'#73dfff';c.shadowBlur=30;c.shadowColor=c.fillStyle;c.beginPath();c.arc(sh.x,sh.y,sh.r,0,7);c.fill();c.shadowBlur=0}for(const sp of g.sparks){c.strokeStyle='#fff1a0';c.lineWidth=5;c.beginPath();c.arc(sp.x,sp.y,sp.size*(.4+sp.life*2),0,7);c.stroke()}if(g.noticeTime>0){c.textAlign='center';c.fillStyle='#fff1bb';c.font='bold 66px sans-serif';c.shadowColor='#ff77b8';c.shadowBlur=15;c.fillText(g.notice,480,235);c.shadowBlur=0;c.textAlign='left'}}
window.addEventListener('keydown',e=>{if(!fg?.running)return;let k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','j','k','l','u','i'].includes(k)){e.preventDefault();fgKeys.add(k)} });
