newFighter=function(x,face){return {...oldNewFighter(x,face),chain:0,chainWindow:0,hitConfirm:0,attackSeq:0,dash:0,dashCD:0,throwCD:0,flash:0,walk:0,stun:0,guard:false,crouch:false,impact:0}};
