function fightText(x,y,label,color='#ffdb7d'){if(fg)fg.fxWords.push({x,y,label,color,life:.7})}
fighterHit=function(target,dmg,source,opts={}){if(!fg?.running)return;const blocking=target.guard&&Math.sign(source.x-target.x)===target.face&&!opts.throw;if(target.dash>0&&opts.projectile)return;const damage=blocking?Math.max(1,Math.round(dmg*.13)):dmg;target.hp=Math.max(0,target.hp-damage);target.stun=blocking?.14:opts.throw?.46:opts.heavy?.33:.20;target.action=blocking?'guard':'hurt';target.anim=target.stun;target.flash=.15;target.x=Math.max(65,Math.min(895,target.x+(target.x>source.x?1:-1)*(blocking?7:opts.throw?74:opts.heavy?42:24)));target.meter=Math.min(100,target.meter+(blocking?3:7));source.hitConfirm=.24;fg.shake=Math.max(fg.shake,blocking?2:opts.heavy?12:7);fg.freeze=blocking?.025:opts.heavy?.085:.05;fightParticle(target.x,target.y-90,blocking?'#72cfff':opts.heavy?'#ffe38e':'#ff7cb8',blocking?6:17);if(source===fg.p&&!blocking){fg.combo=(fg.comboClock>0?fg.combo:0)+1;fg.comboClock=1.3;if(fg.combo>=2)fightText(target.x,target.y-190,`${fg.combo} HITS!`,'#ffe67b')}if(opts.throw)fightText(target.x,target.y-195,'THROW!','#fc91cf');if(blocking)fightText(target.x,target.y-170,'BLOCK','#78dfff');if(target.hp<=0)endFighterRound()};
fighterAttack=function(who,type){if(!fg?.running||who.stun>0)return;const foe=who===fg.p?fg.e:fg.p;const light=type==='light',heavy=type==='heavy',special=type==='special',ultimate=type==='ultimate',throwing=type==='throw';if(throwing&&who.throwCD>0)return;if(who.cd>0&&!(light&&who.chainWindow>0&&who.hitConfirm>0))return;const cost=special?35:ultimate?75:0;if(who.meter<cost)return;who.meter-=cost;who.guard=false;who.crouch=false;if(light){who.chain=(who.chainWindow>0&&who.hitConfirm>0)?(who.chain%3)+1:1;who.chainWindow=.42;who.attackSeq=who.chain}else{who.chain=0;who.chainWindow=0}who.action=type;who.anim=light?.18:heavy?.39:throwing?.32:ultimate?.7:.48;who.cd=light?.22:heavy?.52:throwing?.64:ultimate?.9:.68;if(throwing)who.throwCD=.9;if(special||ultimate){fg.shots.push({x:who.x+who.face*62,y:who.y-93,face:who.face,owner:who,damage:ultimate?32:16,life:1.45,r:ultimate?35:21,heavy:ultimate});fightParticle(who.x+who.face*60,who.y-92,ultimate?'#fce0a2':'#8feaff',18);fg.shake=ultimate?12:4;beep('win');return}const reach=throwing?86:heavy?153:who.chain===3?146:118;const inRange=Math.abs(foe.x-who.x)<reach&&Math.abs(foe.y-who.y)<(throwing?35:75)&&Math.sign(foe.x-who.x)===who.face;if(inRange){fighterHit(foe,throwing?18:heavy?16:who.chain===3?11:7,who,{heavy:heavy||who.chain===3,throw:throwing});who.meter=Math.min(100,who.meter+(throwing?14:heavy?14:8))}else if(light)who.chainWindow=.19;beep()};
// Reworked 60fps simulation with attack buffering, dash, crouch, CPU defense and impact feedback.
fighterLoop=function(now){if(!fg?.running)return;let dt=Math.min(.033,Math.max(.001,(now-fgLast)/1000));fgLast=now;const g=fg,p=g.p,e=g.e;g.fightTime=(g.fightTime||0)+dt;g.shake=Math.max(0,(g.shake||0)-dt*32);g.comboClock=Math.max(0,(g.comboClock||0)-dt);if(g.freeze>0){g.freeze-=dt;drawFighter();updateFighterHud();fgRAF=requestAnimationFrame(fighterLoop);return}g.t-=dt;for(const q of [p,e]){for(const key of ['cd','stun','anim','chainWindow','hitConfirm','dash','dashCD','throwCD','flash'])q[key]=Math.max(0,(q[key]||0)-dt);q.face=q===p?(p.x<e.x?1:-1):(e.x<p.x?1:-1);if(q.anim<=0&&q.stun<=0)q.action=q.crouch?'crouch':q.guard?'guard':'idle';q.vy+=1750*dt;q.y=Math.min(435,q.y+q.vy*dt);if(q.y===435)q.vy=0}p.crouch=fgKeys.has('ArrowDown')&&p.y===435;p.guard=(fgKeys.has('l')||p.crouch)&&p.y===435;if(p.guard&&p.stun<=0)p.action=p.crouch?'crouch':'guard';if(!p.stun){const m=(fgKeys.has('ArrowRight')?1:0)-(fgKeys.has('ArrowLeft')?1:0);if(fgKeys.has('Shift')&&m&&p.dashCD<=0){p.dash=.16;p.dashCD=.72;fightParticle(p.x,p.y-14,'#86caff',7)}const speed=(p.dash>0?690:230)*(p.fighterStats?.speed||1);if(!p.guard){p.x=Math.max(55,Math.min(905,p.x+m*speed*dt));if(m){p.walk+=dt*13;if(p.anim<=0)p.action=p.dash>0?'dash':'walk'}}if(fgKeys.has('ArrowUp')&&p.y===435&&!p.guard){p.vy=-670;p.action='jump'}for(const [key,kind] of [['j','light'],['k','heavy'],['h','throw'],['u','special'],['i','ultimate']])if(fgKeys.has(key)){fgKeys.delete(key);fighterAttack(p,kind)}}g.aiTimer-=dt;if(g.aiTimer<=0){g.aiTimer=.14+Math.random()*.18;const d=Math.abs(p.x-e.x);if(!e.stun){e.guard=d<170&&Math.random()<.24;e.crouch=e.guard&&Math.random()<.3;if(d>135)e.x+=e.face*(e.dash>0?100:48+g.round*9)*g.aiTimer;else if(d<67&&Math.random()<.25)e.x-=e.face*30;if(d<110&&p.guard&&Math.random()<.28)fighterAttack(e,'throw');else if(d<150&&Math.random()<.52)fighterAttack(e,Math.random()<.28?'heavy':'light');else if(d>180&&e.meter>=35&&Math.random()<.25)fighterAttack(e,'special');if(d>160&&Math.random()<.08&&e.y===435)e.vy=-580}}e.x=Math.max(55,Math.min(905,e.x));if(e.guard&&e.stun<=0)e.action='guard';if(e.y<435&&e.stun<=0)e.action='jump';for(const sh of g.shots){sh.x+=sh.face*(sh.heavy?530:480)*dt;sh.life-=dt;const target=sh.owner===p?e:p;if(Math.abs(sh.x-target.x)<sh.r+27&&Math.abs(sh.y-(target.y-90))<63){fighterHit(target,sh.damage,sh.owner,{heavy:sh.heavy,projectile:true});sh.life=0}}g.shots=g.shots.filter(sh=>sh.life>0&&sh.x>-50&&sh.x<1010);g.sparks=g.sparks.filter(sp=>(sp.life-=dt)>0);g.dust=g.dust.filter(v=>{v.x+=v.vx*dt;v.y+=v.vy*dt;v.vy+=450*dt;return (v.life-=dt)>0});g.fxWords=g.fxWords.filter(v=>{v.y-=30*dt;return(v.life-=dt)>0});if(g.noticeTime>0)g.noticeTime-=dt;drawFighter();updateFighterHud();if(g.t<=0)endFighterRound();if(fg?.running)fgRAF=requestAnimationFrame(fighterLoop)};
// Layered original vector art: architecture, lanterns, rain reflections, animated silhouette crowd.
