drawFighterPerson=function(c,q,enemy){c.save();c.translate(q.x,q.y);c.scale(q.face,1);const action=q.action||'idle',punch=['light','heavy','special','ultimate'].includes(action),heavy=action==='heavy'||action==='ultimate',hurt=action==='hurt',crouch=q.crouch||action==='crouch',jump=q.y<435,dash=action==='dash';const bob=jump?0:Math.sin((q.walk||performance.now()/160)*.8)*((action==='walk'||dash)?4:1.5);c.translate(0,bob+(crouch?33:0));if(hurt)c.rotate(-.11);if(dash)c.rotate(.13);c.fillStyle='#040b19aa';c.beginPath();c.ellipse(0,4,55,12,0,0,7);c.fill();const jacket=enemy?'#352c36':'#111a35',accent=enemy?'#e58a4f':'#4aaaff',skin=enemy?'#d99875':'#f3bc99',pants=enemy?'#29242e':'#18213d';const stride=action==='walk'?Math.sin(q.walk||0)*16:0;fightLimb(c,[-16,-65],[-24+stride,0],25,pants);fightLimb(c,[15,-65],[25-stride,0],25,pants);fightLimb(c,[-26+stride,-2],[-37+stride,0],15,enemy?'#d6c9c5':'#e9e8ed');fightLimb(c,[25-stride,-2],[39-stride,0],15,enemy?'#d6c9c5':'#e9e8ed');c.fillStyle='#0b1024';c.beginPath();c.moveTo(-38,-137);c.lineTo(24,-139);c.lineTo(37,-69);c.lineTo(-31,-69);c.closePath();c.fill();c.fillStyle=jacket;c.beginPath();c.moveTo(-31,-133);c.lineTo(21,-134);c.lineTo(28,-76);c.lineTo(-26,-76);c.closePath();c.fill();c.strokeStyle=accent;c.lineWidth=3;c.beginPath();c.moveTo(8,-132);c.lineTo(13,-78);c.stroke();c.fillStyle=enemy?'#b95a4d':'#ffce71';c.fillRect(-24,-94,16,4);c.strokeStyle='#ffd36b';c.lineWidth=4;c.beginPath();c.arc(0,-119,15,.2,2.8);c.stroke();const rearArm=punch?[-44,-92]:[-25,-80];fightLimb(c,[-21,-126],rearArm,20,skin);const armEnd=punch?[heavy?110:86,-110]:q.guard?[35,-143]:[45,-79];fightLimb(c,[24,-125],armEnd,21,enemy?skin:'#e0a88d');c.fillStyle=enemy?'#3c282c':'#111a33';c.beginPath();c.arc(...armEnd,13,0,7);c.fill();c.fillStyle=skin;c.beginPath();c.arc(0,-169,30,0,7);c.fill();c.fillStyle=enemy?'#3c2026':'#10172a';c.beginPath();c.moveTo(-30,-171);c.quadraticCurveTo(-35,-212,5,-203);c.quadraticCurveTo(37,-200,29,-169);c.lineTo(20,-186);c.lineTo(10,-175);c.lineTo(1,-190);c.lineTo(-10,-173);c.closePath();c.fill();c.fillStyle='#f7d3b7';c.fillRect(13,-164,12,3);c.fillStyle='#1a1420';c.fillRect(18,-164,5,3);c.strokeStyle=enemy?'#e78b71':'#79c5ff';c.lineWidth=3;c.beginPath();c.moveTo(-28,-139);c.lineTo(-8,-122);c.stroke();if(enemy){c.strokeStyle='#f6a38a';c.lineWidth=3;for(let i=0;i<3;i++){c.beginPath();c.moveTo(-20+i*7,-111);c.lineTo(-28+i*7,-94);c.stroke()}}if(q.guard){c.strokeStyle='#8de8ff';c.lineWidth=5;c.shadowBlur=16;c.shadowColor='#76e3ff';c.beginPath();c.arc(0,-112,70,-1.5,1.15);c.stroke();c.shadowBlur=0}if(q.flash>0){c.globalCompositeOperation='screen';c.fillStyle='#ffffff77';c.beginPath();c.ellipse(0,-105,48,102,0,0,7);c.fill()}c.restore()};
drawFighter=function(){const canvas=$('fighterCanvas');if(!canvas||!fg)return;const c=canvas.getContext('2d'),g=fg;c.save();if(g.shake){c.translate((Math.random()-.5)*g.shake,(Math.random()-.5)*g.shake)}drawFightStage(c,g.t);drawFighterPerson(c,g.p,false);drawFighterPerson(c,g.e,true);for(const sh of g.shots){const grad=c.createRadialGradient(sh.x,sh.y,3,sh.x,sh.y,sh.r*2);grad.addColorStop(0,'#fff');grad.addColorStop(.3,sh.owner===g.p?'#ffe68a':'#91f1ff');grad.addColorStop(1,'#ff6c8a00');c.fillStyle=grad;c.beginPath();c.arc(sh.x,sh.y,sh.r*2,0,7);c.fill();c.strokeStyle=sh.owner===g.p?'#ffcf7c':'#70dfff';c.lineWidth=3;c.beginPath();c.arc(sh.x,sh.y,sh.r*1.3,0,7);c.stroke()}for(const v of g.dust||[]){c.globalAlpha=Math.min(1,v.life/v.max);c.fillStyle=v.color;c.fillRect(v.x,v.y,v.size,v.size);c.globalAlpha=1}for(const v of g.fxWords||[]){c.globalAlpha=Math.min(1,v.life/.35);c.font='italic 900 31px sans-serif';c.strokeStyle='#170f2c';c.lineWidth=6;c.strokeText(v.label,v.x-45,v.y);c.fillStyle=v.color;c.fillText(v.label,v.x-45,v.y);c.globalAlpha=1}for(const sp of g.sparks){c.strokeStyle='#fff1a0';c.lineWidth=4;c.beginPath();c.arc(sp.x,sp.y,sp.size*(.4+sp.life*2),0,7);c.stroke()}if(g.noticeTime>0){c.textAlign='center';c.fillStyle='#fff0a9';c.font='italic 900 67px sans-serif';c.shadowColor='#ff568e';c.shadowBlur=20;c.fillText(g.notice,480,260);c.shadowBlur=0;c.textAlign='left'}c.restore()};
