function startTraining65(){if(fg?.running)return;const old=s.energy;s.energy=Math.max(s.energy,10);startFighter();s.energy=old;save();if(!fg?.running)return;training65=true;fg.training65=true;fg.t=999;fg.e.stun=999;fg.e.meter=0;fg.p.meter=100;const mask=$('fgMask');if(mask)mask.classList.add('hidden');toast('自由練習開始：對手不反擊，按「結束練習」返回');}
