const attackBefore65=fighterAttack;
fighterAttack=function(who,type){if(!fg?.running)return;const isPlayer=who===fg.p,stats=isPlayer?roster65.find(c=>c.id===fighterPick65):null;const before=fg.e.hp;if(stats&&stats.damage!==1){who._damage65=stats.damage}attackBefore65(who,type);if(stats&&fg?.e&&fg.e.hp<before){const dealt=before-fg.e.hp;fg.e.hp=Math.max(0,Math.min(100,before-Math.max(1,Math.round(dealt*stats.damage))))}if(training65&&fg){fg.e.hp=Math.max(1,fg.e.hp);fg.p.meter=Math.max(35,fg.p.meter)}};
